'use strict';
window.MASTER_LAB_FERROPENIA={'id':'lab_ferropenia_piloto_v1','title':'Laboratório de Exames · Anemia microcítica','version':'2026.11.15.2','status':'piloto integrado para estudo, em revisão docente','baseCommit':'83fbfeb0739a1fb06de9f4b3916f7218b41f9805','REFS':{'inflamacao':{'t':'Weiss, Ganz e Goodnough. Anemia of inflammation. Blood, volume 133, 2019; publicação online em 2018. DOI 10.1182/blood-2018-06-856500.','u':'https://pmc.ncbi.nlm.nih.gov/articles/PMC6536698/','year':'2019','status':'texto consultado em 15/11/2026','scope':'Hepcidina, restrição de ferro, ferritina e coexistência de mecanismos. Revisão, não diretriz universal.'},'idosos':{'t':'Oyedeji e colaboradores. How I treat anemia in older adults. Blood, volume 143, edição de 2024; publicação online em 2023. DOI 10.1182/blood.2022017626.','u':'https://pmc.ncbi.nlm.nih.gov/articles/PMC10808247/','year':'2023/2024','status':'texto consultado em 15/11/2026','scope':'Abordagem de anemia em adultos mais velhos. Os casos e as tabelas do artigo não foram reproduzidos.'},'ckd':{'t':'NICE NG203. Chronic kidney disease: assessment and management. 2021, recomendações 1.7.3 e 1.7.4 na página vigente consultada em 15/11/2026.','u':'https://www.nice.org.uk/guidance/ng203/chapter/Recommendations','year':'2021','status':'recomendações consultadas em 15/11/2026','scope':'Combinar parâmetros de ferro na anemia da DRC. Não extrapolar os limites de DRC para todos os adultos.'},'celiaca':{'t':'NICE NG20. Coeliac disease: recognition, assessment and management. 2015, recomendações 1.1.1 e 1.2.2 na página vigente consultada em 15/11/2026.','u':'https://www.nice.org.uk/guidance/ng20/chapter/Recommendations','year':'2015','status':'recomendações consultadas em 15/11/2026','scope':'Investigar deficiência de ferro inexplicada; IgA total e anti-transglutaminase IgA como primeira estratégia sorológica em adultos, conforme contexto.'},'cancer':{'t':'NICE NG12. Suspected cancer: recognition and referral. 2015, recomendações colorretais 1.3.1 a 1.3.3 atualizadas em 2023; página vigente consultada em 15/11/2026.','u':'https://www.nice.org.uk/guidance/ng12/chapter/1-recommendations-organised-by-site-of-cancer','year':'2015/2023','status':'recomendações consultadas em 15/11/2026','scope':'Investigação colorretal e seguimento de segurança. O fluxo do NHS não equivale automaticamente a um protocolo brasileiro.'}},'MODULES':[{'id':'lab_ferro_01','layer':'Unidade piloto · Ler o laudo','title':'Microcitose: confirme o problema antes de nomear a causa','min':20,'summary':'Qualidade, três séries, índices e unidades. Aprenda a separar padrão hematimétrico de diagnóstico etiológico.','goals':['Validar a amostra e localizar a alteração nas três séries.','Calcular VCM e saturação de transferrina sem misturar unidades.','Distinguir pistas de microcitose de confirmação etiológica.'],'pretest':['Microcitose basta para diagnosticar falta de ferro?','Pode dividir ferro em µg/dL por capacidade de ligação em µmol/L?','Um RDW dentro do intervalo exclui ferropenia?'],'sections':[{'h':'Primeiro: o laudo pertence a uma história','p':['Confirme identificação, data, condições da coleta, comentários do laboratório e comparação com exames anteriores. Verifique se os números combinam entre si. Diluição por infusão, coágulos e alertas analíticos podem alterar o resultado. A investigação da amostra não pode atrasar atendimento de quem está instável.','Neste piloto, todos os pacientes e resultados são fictícios. Os intervalos impressos nos casos são referências do laboratório inventado do exercício, não faixas que devam ser usadas no seu serviço. Não aplicamos pontos de corte de gestantes ou crianças a adultos.']},{'h':'Leia as três séries antes de focar no VCM','list':['Série vermelha: hemoglobina, hematócrito, número de hemácias, VCM, HCM e RDW.','Série branca: contagem total, diferencial absoluto e comentários de morfologia.','Plaquetas: contagem, tendência e agregados.','Contexto: sangramento, sintomas, inflamação, rim, alimentação, história familiar e medicamentos.'],'after':'Uma trombocitose pode acompanhar deficiência de ferro, mas não a confirma. Citopenias combinadas, blastos ou sinais de hemólise mudam a investigação e a prioridade.'},{'h':'O que os índices medem','table':{'head':['Parâmetro','O que informa','Limite da interpretação'],'rows':[['VCM','Volume médio das hemácias','Uma média pode esconder populações pequenas e grandes juntas.'],['HCM e CHCM','Hemoglobina por célula e concentração média','Não identificam a causa da anemia sozinhas.'],['RDW','Dispersão do tamanho das hemácias','É uma pista; a distribuição se sobrepõe entre doenças.'],['Reticulócitos','Resposta eritropoiética recente','Percentual isolado pode enganar quando há anemia.']]}},{'h':'Contas com as unidades à vista','p':['VCM em fL = hematócrito em % × 10 ÷ hemácias em milhões/µL. No exemplo fictício, 30,8 × 10 ÷ 4,4 = 70 fL. HCM em pg = hemoglobina em g/dL × 10 ÷ hemácias em milhões/µL.','Saturação de transferrina em % = ferro sérico ÷ capacidade total de ligação do ferro × 100, somente quando os dois estão em unidades compatíveis. Ferro de 24 µg/dL e capacidade de 400 µg/dL produzem 6%. Não usar essa conta diretamente com transferrina em mg/dL.','Essas contas são relações de unidades, não classificadores automáticos. O resultado precisa ser interpretado com ferritina, inflamação e o contexto.']},{'h':'Microcitose não é sinônimo de ferropenia','table':{'head':['Hipótese','Pistas que ajudam','Como não cair na armadilha'],'rows':[['Deficiência absoluta de ferro','Estoques reduzidos e ferro indisponível; buscar perdas ou absorção inadequada.','Não concluir apenas por ferro sérico baixo.'],['Inflamação','Restrição de ferro mediada por hepcidina; ferritina pode aumentar.','Ferritina dentro do intervalo não exclui mecanismo misto.'],['Traço talassêmico','Microcitose antiga, história familiar e hemácias relativamente preservadas.','Índices de triagem não substituem estudo de hemoglobinas.'],['Outras causas selecionadas','Exposições, medicamentos ou alterações hematológicas específicas.','Investigar quando história e resultados dirigirem, sem pedir todos os testes a todos.']]}},{'h':'Resposta curta que demonstra raciocínio','p':['Use esta sequência: identifique a síndrome, descreva o padrão, diga o que favorece cada hipótese e indique o próximo exame ou etapa que resolveria a dúvida. Evite anunciar uma causa definitiva a partir de uma pista.','Exemplo autoral: Há anemia com microcitose neste laudo. A deficiência de ferro é plausível, mas preciso interpretar ferritina com marcadores de inflamação e investigar perdas. O VCM isolado não separa deficiência absoluta de restrição inflamatória.']}],'pitfalls':['Ignorar leucócitos e plaquetas depois de encontrar anemia.','Dividir grandezas com unidades diferentes e aceitar um percentual aparentemente plausível.','Usar RDW ou contagem de hemácias como confirmação de talassemia.','Tratar intervalos fictícios deste exercício como padrões universais.'],'quiz':[{'id':'ferro-q01','level':'N2','q':'Um laudo fictício mostra Hb 9,6 g/dL, Ht 30,8% e hemácias 4,4 milhões/µL. Qual interpretação da conta do VCM é correta?','o':['VCM de 70 fL, que descreve o tamanho médio sem definir a causa','VCM de 7 fL, que confirma ferropenia','VCM de 135 fL, que confirma deficiência de B12','A conta define traço talassêmico'],'a':0,'why':'Sobre VCM de 70 fL, que descreve o tamanho médio sem definir a causa: A fórmula com essas unidades fornece 70 fL. A etiologia exige integração com outros dados. Sobre VCM de 7 fL, que confirma ferropenia: Há erro de escala e a microcitose não confirma deficiência de ferro sozinha. Sobre VCM de 135 fL, que confirma deficiência de B12: A operação não corresponde à fórmula e não demonstra deficiência vitamínica. Sobre A conta define traço talassêmico: Nenhuma relação entre Ht e hemácias confirma uma hemoglobinopatia.','explanations':{'VCM de 70 fL, que descreve o tamanho médio sem definir a causa':'A fórmula com essas unidades fornece 70 fL. A etiologia exige integração com outros dados.','VCM de 7 fL, que confirma ferropenia':'Há erro de escala e a microcitose não confirma deficiência de ferro sozinha.','VCM de 135 fL, que confirma deficiência de B12':'A operação não corresponde à fórmula e não demonstra deficiência vitamínica.','A conta define traço talassêmico':'Nenhuma relação entre Ht e hemácias confirma uma hemoglobinopatia.'},'refs':['inflamacao','idosos']},{'id':'ferro-q02','level':'N2','q':'Ferro sérico 24 µg/dL e capacidade total de ligação 400 µg/dL foram medidos na mesma amostra. Qual resultado aritmético está correto?','o':['Saturação de 16,7%, suficiente para definir inflamação','Saturação de 60%, suficiente para definir sobrecarga','Não se pode calcular porque as unidades são iguais','Saturação de 6%, com etiologia ainda dependente do contexto'],'a':3,'why':'Sobre Saturação de 6%, com etiologia ainda dependente do contexto: 24 dividido por 400, multiplicado por 100, é 6. O cálculo não diferencia sozinho os mecanismos. Sobre Saturação de 16,7%, suficiente para definir inflamação: A inversão ou outra operação não fornece a saturação, e o diagnóstico não vem da conta isolada. Sobre Saturação de 60%, suficiente para definir sobrecarga: Houve erro de escala; essa conclusão não é sustentada pelos dados. Sobre Não se pode calcular porque as unidades são iguais: Unidades compatíveis permitem a razão. O problema seria misturar unidades ou analitos diferentes.','explanations':{'Saturação de 6%, com etiologia ainda dependente do contexto':'24 dividido por 400, multiplicado por 100, é 6. O cálculo não diferencia sozinho os mecanismos.','Saturação de 16,7%, suficiente para definir inflamação':'A inversão ou outra operação não fornece a saturação, e o diagnóstico não vem da conta isolada.','Saturação de 60%, suficiente para definir sobrecarga':'Houve erro de escala; essa conclusão não é sustentada pelos dados.','Não se pode calcular porque as unidades são iguais':'Unidades compatíveis permitem a razão. O problema seria misturar unidades ou analitos diferentes.'},'refs':['inflamacao','idosos']},{'id':'ferro-q03','level':'N3','q':'Um laboratório envia ferro em µg/dL e capacidade de ligação em µmol/L. O estudante calcula a saturação dividindo os valores diretamente. O melhor retorno é:','o':['Dividir a ferritina pela hemoglobina para corrigir','Usar transferrina em mg/dL como se fosse capacidade de ligação em µg/dL','Interromper a interpretação da razão e obter valores em unidades compatíveis','Aceitar a conta se o resultado estiver entre zero e cem'],'a':2,'why':'Sobre Interromper a interpretação da razão e obter valores em unidades compatíveis: A compatibilidade de unidades é pré-requisito. Reemissão ou conversão validada deve preceder a conta. Sobre Aceitar a conta se o resultado estiver entre zero e cem: Um número plausível pode estar errado por dimensionalidade; aparência não valida cálculo. Sobre Dividir a ferritina pela hemoglobina para corrigir: São medidas diferentes e essa divisão não produz saturação. Sobre Usar transferrina em mg/dL como se fosse capacidade de ligação em µg/dL: Transferrina e capacidade de ligação não são intercambiáveis sem relação de conversão validada.','explanations':{'Interromper a interpretação da razão e obter valores em unidades compatíveis':'A compatibilidade de unidades é pré-requisito. Reemissão ou conversão validada deve preceder a conta.','Aceitar a conta se o resultado estiver entre zero e cem':'Um número plausível pode estar errado por dimensionalidade; aparência não valida cálculo.','Dividir a ferritina pela hemoglobina para corrigir':'São medidas diferentes e essa divisão não produz saturação.','Usar transferrina em mg/dL como se fosse capacidade de ligação em µg/dL':'Transferrina e capacidade de ligação não são intercambiáveis sem relação de conversão validada.'},'refs':['inflamacao','idosos']},{'id':'ferro-q04','level':'N2','q':'Após coleta em acesso com infusão, as três séries caem abruptamente sem mudança clínica. Qual próximo passo melhor evita um erro de interpretação?','o':['Confirmar aplasia medular pelo hemograma isolado','Investigar diluição e confirmar amostra adequada, sem ignorar sinais de urgência','Diagnosticar três doenças independentes','Ignorar o resultado definitivamente'],'a':1,'why':'Sobre Investigar diluição e confirmar amostra adequada, sem ignorar sinais de urgência: O contexto de coleta pode explicar o padrão; revisão e recoleta esclarecem sem suspender atendimento necessário. Sobre Diagnosticar três doenças independentes: A coincidência exige verificar a amostra antes de atribuir causas independentes. Sobre Ignorar o resultado definitivamente: Discordância com a clínica pede esclarecimento, não descarte definitivo. Sobre Confirmar aplasia medular pelo hemograma isolado: Falência medular não se confirma por essa trajetória isolada.','explanations':{'Investigar diluição e confirmar amostra adequada, sem ignorar sinais de urgência':'O contexto de coleta pode explicar o padrão; revisão e recoleta esclarecem sem suspender atendimento necessário.','Diagnosticar três doenças independentes':'A coincidência exige verificar a amostra antes de atribuir causas independentes.','Ignorar o resultado definitivamente':'Discordância com a clínica pede esclarecimento, não descarte definitivo.','Confirmar aplasia medular pelo hemograma isolado':'Falência medular não se confirma por essa trajetória isolada.'},'refs':['inflamacao','idosos']},{'id':'ferro-q05','level':'N2','q':'Um adulto tem microcitose e RDW dentro do intervalo do seu laboratório. Qual conclusão é adequada?','o':['O RDW não resolve sozinho a distinção entre ferropenia e traço talassêmico','Ferropenia está definitivamente excluída','Talassemia está confirmada','A hemoglobina deixa de ser relevante'],'a':0,'why':'Sobre O RDW não resolve sozinho a distinção entre ferropenia e traço talassêmico: Há sobreposição de padrões; história, ferro e estudo de hemoglobinas podem ser necessários. Sobre Ferropenia está definitivamente excluída: O parâmetro não tem poder de exclusão universal. Sobre Talassemia está confirmada: Uma pista de distribuição de tamanhos não é confirmação etiológica. Sobre A hemoglobina deixa de ser relevante: A avaliação de anemia continua dependendo de Hb, contexto e demais séries.','explanations':{'O RDW não resolve sozinho a distinção entre ferropenia e traço talassêmico':'Há sobreposição de padrões; história, ferro e estudo de hemoglobinas podem ser necessários.','Ferropenia está definitivamente excluída':'O parâmetro não tem poder de exclusão universal.','Talassemia está confirmada':'Uma pista de distribuição de tamanhos não é confirmação etiológica.','A hemoglobina deixa de ser relevante':'A avaliação de anemia continua dependendo de Hb, contexto e demais séries.'},'refs':['inflamacao','idosos']},{'id':'ferro-q06','level':'N3','q':'A pessoa tem microcitose antiga, pai com padrão semelhante e hemácias relativamente preservadas. Qual estratégia é mais consistente?','o':['Prescrever ferro por toda a vida pela microcitose','Descartar deficiência de ferro apenas pela história familiar','Considerar o diagnóstico encerrado se a eletroforese for normal','Investigar hemoglobinopatia e estado do ferro sem atribuir etiologia por um índice isolado'],'a':3,'why':'Sobre Investigar hemoglobinopatia e estado do ferro sem atribuir etiologia por um índice isolado: O conjunto orienta a investigação e permite reconhecer condições concomitantes. Sobre Prescrever ferro por toda a vida pela microcitose: Não se demonstrou deficiência que sustente essa decisão, nem se investigou a causa. Sobre Descartar deficiência de ferro apenas pela história familiar: História familiar e ferropenia podem coexistir. Sobre Considerar o diagnóstico encerrado se a eletroforese for normal: Algumas formas de talassemia podem não ser identificadas pelo estudo inicial; contexto e avaliação especializada continuam importantes.','explanations':{'Investigar hemoglobinopatia e estado do ferro sem atribuir etiologia por um índice isolado':'O conjunto orienta a investigação e permite reconhecer condições concomitantes.','Prescrever ferro por toda a vida pela microcitose':'Não se demonstrou deficiência que sustente essa decisão, nem se investigou a causa.','Descartar deficiência de ferro apenas pela história familiar':'História familiar e ferropenia podem coexistir.','Considerar o diagnóstico encerrado se a eletroforese for normal':'Algumas formas de talassemia podem não ser identificadas pelo estudo inicial; contexto e avaliação especializada continuam importantes.'},'refs':['inflamacao','idosos']}],'refs':['inflamacao','idosos']},{'id':'lab_ferro_02','layer':'Unidade piloto · Entender o mecanismo','title':'Ferritina, hepcidina e o ferro que não chega à medula','min':25,'summary':'Separe estoque reduzido de ferro sequestrado e reconheça quando os dois mecanismos coexistem.','goals':['Explicar a ação da hepcidina sobre a ferroportina.','Interpretar ferritina, saturação e inflamação em conjunto.','Reconhecer os limites das referências de laboratório e das regras de outras populações.'],'pretest':['Como a inflamação pode reduzir ferro circulante e aumentar ferritina?','Uma ferritina elevada prova que a medula recebe ferro suficiente?','Pode usar automaticamente um critério de DRC em uma pessoa sem doença renal?'],'sections':[{'h':'Deficiência absoluta e restrição funcional são perguntas diferentes','p':['Na deficiência absoluta, os estoques se reduzem. Na restrição inflamatória, parte do ferro permanece retida e menos disponível para a eritropoese. Os dois mecanismos podem ocorrer no mesmo paciente. Por isso, não é obrigatório escolher entre apenas falta de ferro ou apenas inflamação.','A anemia inflamatória também envolve alteração da resposta eritropoiética e da sobrevida das hemácias. Reduzir toda a explicação ao ferro sérico perde parte do mecanismo.']},{'h':'O caminho da hepcidina explica o laudo','list':['A inflamação favorece aumento de hepcidina produzida pelo fígado.','A hepcidina reduz a disponibilidade de ferroportina nas células que exportam ferro.','Cai a liberação de ferro de macrófagos e a absorção intestinal efetiva.','A medula recebe menos ferro circulante, mesmo quando os estoques não estão esgotados.'],'after':'Ferritina é também reagente de fase aguda. O valor pode aumentar com inflamação e não deve ser traduzido automaticamente como ferro disponível para produzir hemácias.'},{'h':'Compare padrões, sem transformá-los em carimbos','table':{'head':['Medida','Deficiência absoluta sem inflamação','Restrição inflamatória'],'rows':[['Ferritina','Tende a cair com a redução dos estoques.','Pode estar preservada ou elevada pela fase aguda.'],['Ferro e saturação','Podem diminuir.','Também podem diminuir.'],['Capacidade de ligação','Pode aumentar.','Pode diminuir ou não aumentar.'],['PCR e contexto','Ajudam a identificar inflamação concomitante.','Apoiam contexto, mas não comprovam a causa de toda a anemia.'],['Reticulócitos','A resposta pode estar inadequada para a anemia.','Também pode ser limitada; investigar outros mecanismos.']]}},{'h':'Quando a ferritina não resolve','p':['Integre o valor com inflamação, saturação, história de perdas, exames anteriores e comorbidades. Conteúdo de hemoglobina dos reticulócitos ou receptor solúvel de transferrina podem ajudar em situações selecionadas, conforme disponibilidade, método e interpretação especializada. Não são substitutos automáticos para a história clínica.','Neste piloto, não há ponto de corte único que transforme uma ferritina intermediária em diagnóstico. Os exemplos demonstram raciocínio probabilístico e limites de cada dado.']},{'h':'Critério de um contexto não é regra universal','p':['Na anemia da DRC, a NICE NG203 recomenda não avaliar o estado de ferro com ferritina ou saturação isoladamente. Isso sustenta a necessidade de integrar medidas nessa população; não autoriza transportar todo limiar de DRC para um adulto sem doença renal.','Os pontos de corte de documentos da AGA, BSG e OMS citados na base publicada não foram reconferidos nesta rodada por indisponibilidade de acesso. Eles não foram incorporados como regras numéricas universais neste piloto. Conferência desses pontos e aplicação ao contexto brasileiro: a confirmar.']},{'h':'Exemplo resolvido autoral','p':['No laudo fictício, ferro 20 µg/dL e capacidade 200 µg/dL produzem saturação de 10%. A ferritina está em 180 ng/mL e a PCR aumentou no mesmo período de atividade inflamatória. O padrão favorece restrição inflamatória, mas não prova ausência de deficiência absoluta associada.','A próxima etapa depende da pergunta que permanece: há perdas, deficiência anterior, doença renal ou outra causa de resposta medular inadequada? A resposta precisa ser procurada; não cabe ao número isolado encerrar a investigação.']}],'pitfalls':['Usar ferro sérico baixo como sinônimo de estoque baixo.','Tratar ferritina dentro do intervalo como exclusão de ferropenia em pessoa inflamada.','Confundir evidência de inflamação com prova de que toda a anemia é inflamatória.','Aplicar um limite de DRC, gestação ou outra população sem confirmar a indicação.'],'quiz':[{'id':'ferro-q07','level':'N2','q':'Durante atividade inflamatória, ferro e saturação caem, enquanto a ferritina aumenta. Qual mecanismo melhor integra o conjunto?','o':['Aumento obrigatório dos estoques causado por toda inflamação','Hemólise confirmada sem outros dados','A ferritina mede diretamente o ferro entregue à medula','Aumento de hepcidina e menor exportação de ferro pela ferroportina'],'a':3,'why':'Sobre Aumento de hepcidina e menor exportação de ferro pela ferroportina: O mecanismo reduz ferro disponível e a fase aguda pode elevar ferritina. Sobre Aumento obrigatório dos estoques causado por toda inflamação: Ferritina pode subir sem representar ganho proporcional de estoques, e deficiência absoluta pode coexistir. Sobre Hemólise confirmada sem outros dados: Hemólise exige outras evidências; esse padrão não a confirma. Sobre A ferritina mede diretamente o ferro entregue à medula: Ferritina não é medida direta de entrega de ferro à eritropoese.','explanations':{'Aumento de hepcidina e menor exportação de ferro pela ferroportina':'O mecanismo reduz ferro disponível e a fase aguda pode elevar ferritina.','Aumento obrigatório dos estoques causado por toda inflamação':'Ferritina pode subir sem representar ganho proporcional de estoques, e deficiência absoluta pode coexistir.','Hemólise confirmada sem outros dados':'Hemólise exige outras evidências; esse padrão não a confirma.','A ferritina mede diretamente o ferro entregue à medula':'Ferritina não é medida direta de entrega de ferro à eritropoese.'},'refs':['inflamacao','idosos']},{'id':'ferro-q08','level':'N3','q':'Uma paciente inflamada tem anemia, ferritina dentro do intervalo e saturação reduzida. Qual afirmação evita a conclusão excessiva?','o':['Saturação baixa confirma deficiência absoluta sem inflamação','A PCR elevada explica qualquer citopenia sem investigação','Restrição de ferro é plausível; deficiência absoluta associada ainda precisa ser avaliada','Ferritina dentro do intervalo exclui deficiência de ferro em qualquer contexto'],'a':2,'why':'Sobre Restrição de ferro é plausível; deficiência absoluta associada ainda precisa ser avaliada: Fase aguda e mecanismos combinados limitam a leitura isolada da ferritina. Sobre Ferritina dentro do intervalo exclui deficiência de ferro em qualquer contexto: A interpretação depende de contexto e população; o intervalo não fornece essa exclusão universal. Sobre Saturação baixa confirma deficiência absoluta sem inflamação: A saturação também pode reduzir na inflamação sem depleção completa de estoques. Sobre A PCR elevada explica qualquer citopenia sem investigação: Inflamação não substitui análise das séries nem exclui doença concomitante.','explanations':{'Restrição de ferro é plausível; deficiência absoluta associada ainda precisa ser avaliada':'Fase aguda e mecanismos combinados limitam a leitura isolada da ferritina.','Ferritina dentro do intervalo exclui deficiência de ferro em qualquer contexto':'A interpretação depende de contexto e população; o intervalo não fornece essa exclusão universal.','Saturação baixa confirma deficiência absoluta sem inflamação':'A saturação também pode reduzir na inflamação sem depleção completa de estoques.','A PCR elevada explica qualquer citopenia sem investigação':'Inflamação não substitui análise das séries nem exclui doença concomitante.'},'refs':['inflamacao','idosos']},{'id':'ferro-q09','level':'N2','q':'Qual combinação descreve melhor deficiência absoluta de ferro sem inflamação relevante?','o':['Hemácias preservadas tornando a deficiência impossível','Estoques reduzidos com ferritina diminuída, interpretados com a história','Ferritina necessariamente elevada em todos os pacientes','Ferro sérico isolado suficiente para definir a causa'],'a':1,'why':'Sobre Estoques reduzidos com ferritina diminuída, interpretados com a história: O padrão é compatível, e a investigação deve buscar por que os estoques caíram. Sobre Ferritina necessariamente elevada em todos os pacientes: Elevação pode ocorrer em outros contextos; não é o padrão obrigatório da depleção isolada. Sobre Ferro sérico isolado suficiente para definir a causa: O ferro circulante sofre variação e redução por diferentes mecanismos. Sobre Hemácias preservadas tornando a deficiência impossível: A contagem de hemácias não tem esse poder de exclusão.','explanations':{'Estoques reduzidos com ferritina diminuída, interpretados com a história':'O padrão é compatível, e a investigação deve buscar por que os estoques caíram.','Ferritina necessariamente elevada em todos os pacientes':'Elevação pode ocorrer em outros contextos; não é o padrão obrigatório da depleção isolada.','Ferro sérico isolado suficiente para definir a causa':'O ferro circulante sofre variação e redução por diferentes mecanismos.','Hemácias preservadas tornando a deficiência impossível':'A contagem de hemácias não tem esse poder de exclusão.'},'refs':['inflamacao','idosos']},{'id':'ferro-q10','level':'N3','q':'Um estudante usa um limiar de uma diretriz de anemia da DRC em adulto sem DRC e dispensa investigação adicional. Qual o problema principal?','o':['Extrapolou uma regra de população específica sem confirmar aplicabilidade','A diretriz de DRC é automaticamente inválida para todos','Todo resultado de ferritina dispensa interpretação clínica','A unidade ng/mL invalida qualquer dosagem de ferritina'],'a':0,'why':'Sobre Extrapolou uma regra de população específica sem confirmar aplicabilidade: Indicação, método e população fazem parte da regra; não basta copiar o número. Sobre A diretriz de DRC é automaticamente inválida para todos: A fonte pode ser apropriada no seu contexto. O erro foi extrapolação. Sobre Todo resultado de ferritina dispensa interpretação clínica: Interpretação clínica continua necessária, inclusive no contexto original da diretriz. Sobre A unidade ng/mL invalida qualquer dosagem de ferritina: A unidade é usada para ferritina; é preciso verificar unidade e método, não rejeitá-la por princípio.','explanations':{'Extrapolou uma regra de população específica sem confirmar aplicabilidade':'Indicação, método e população fazem parte da regra; não basta copiar o número.','A diretriz de DRC é automaticamente inválida para todos':'A fonte pode ser apropriada no seu contexto. O erro foi extrapolação.','Todo resultado de ferritina dispensa interpretação clínica':'Interpretação clínica continua necessária, inclusive no contexto original da diretriz.','A unidade ng/mL invalida qualquer dosagem de ferritina':'A unidade é usada para ferritina; é preciso verificar unidade e método, não rejeitá-la por princípio.'},'refs':['ckd','inflamacao']},{'id':'ferro-q11','level':'N3','q':'Uma pessoa já apresentava estoques de ferro reduzidos antes de uma doença inflamatória. Sem reposição ou correção da causa, a ferritina agora aumentou. Qual leitura é mais prudente?','o':['A elevação prova reposição espontânea de todo o ferro perdido','O exame antigo nunca tem utilidade','Inflamação e deficiência absoluta são mutuamente exclusivas','Considerar mecanismo misto e integrar a trajetória em vez de declarar estoque corrigido'],'a':3,'why':'Sobre Considerar mecanismo misto e integrar a trajetória em vez de declarar estoque corrigido: A mudança de fase aguda pode explicar parte do aumento; a história de depleção continua relevante. Sobre A elevação prova reposição espontânea de todo o ferro perdido: O marcador pode variar com inflamação sem demonstrar correção dos estoques. Sobre O exame antigo nunca tem utilidade: A trajetória ajuda a revelar mecanismos que uma amostra isolada oculta. Sobre Inflamação e deficiência absoluta são mutuamente exclusivas: Os mecanismos podem coexistir e precisam ser avaliados em conjunto.','explanations':{'Considerar mecanismo misto e integrar a trajetória em vez de declarar estoque corrigido':'A mudança de fase aguda pode explicar parte do aumento; a história de depleção continua relevante.','A elevação prova reposição espontânea de todo o ferro perdido':'O marcador pode variar com inflamação sem demonstrar correção dos estoques.','O exame antigo nunca tem utilidade':'A trajetória ajuda a revelar mecanismos que uma amostra isolada oculta.','Inflamação e deficiência absoluta são mutuamente exclusivas':'Os mecanismos podem coexistir e precisam ser avaliados em conjunto.'},'refs':['inflamacao','idosos']},{'id':'ferro-q12','level':'N2','q':'Qual é a principal limitação de uma ferritina dentro do intervalo impresso no laudo?','o':['Esse resultado confirma automaticamente sobrecarga de ferro','Ele substitui a investigação de perdas','O intervalo não incorpora sozinho inflamação, população, método e pergunta diagnóstica','O resultado não pode ser usado em raciocínio algum'],'a':2,'why':'Sobre O intervalo não incorpora sozinho inflamação, população, método e pergunta diagnóstica: Referência laboratorial e limite de decisão clínica são conceitos relacionados, mas não idênticos. Sobre O resultado não pode ser usado em raciocínio algum: O resultado é útil quando integrado ao contexto e a outros dados. Sobre Esse resultado confirma automaticamente sobrecarga de ferro: Estar dentro de um intervalo não confirma sobrecarga. Sobre Ele substitui a investigação de perdas: O marcador não explica por si só a origem de uma anemia ou de estoques reduzidos.','explanations':{'O intervalo não incorpora sozinho inflamação, população, método e pergunta diagnóstica':'Referência laboratorial e limite de decisão clínica são conceitos relacionados, mas não idênticos.','O resultado não pode ser usado em raciocínio algum':'O resultado é útil quando integrado ao contexto e a outros dados.','Esse resultado confirma automaticamente sobrecarga de ferro':'Estar dentro de um intervalo não confirma sobrecarga.','Ele substitui a investigação de perdas':'O marcador não explica por si só a origem de uma anemia ou de estoques reduzidos.'},'refs':['inflamacao','idosos']}],'refs':['inflamacao','idosos','ckd']},{'id':'lab_ferro_03','layer':'Unidade piloto · Decidir o próximo passo','title':'Investigar a causa sem perder a prioridade clínica','min':25,'summary':'Integre perdas, inflamação, absorção e hemoglobinopatias e comunique uma decisão justificável.','goals':['Diferenciar urgência clínica de investigação programada.','Buscar a origem da deficiência e reconhecer sinais que ampliam a investigação.','Registrar hipótese, incerteza e próximo passo com linguagem clara.'],'pretest':['Melhorar a hemoglobina encerra a investigação da causa?','Um teste fecal negativo exclui câncer em pessoa com sinais persistentes?','Por que deficiência de ferro inexplicada pode levar à investigação de doença celíaca?'],'sections':[{'h':'A primeira decisão é a prioridade','p':['Instabilidade, sangramento ativo importante, dor torácica, dispneia relevante em repouso ou outros sinais de comprometimento exigem avaliação imediata. Nenhum valor isolado substitui essa avaliação. Este piloto ensina interpretação e não define limiares de transfusão nem doses de ferro.','Em pessoa estável, construa uma investigação dirigida: confirme o padrão, formule os mecanismos prováveis, identifique fontes de perda e considere absorção e doenças concomitantes.']},{'h':'Procure por que o ferro faltou','table':{'head':['Pergunta','O que explorar','Como isso orienta o próximo passo'],'rows':[['Há perda?','História menstrual, digestiva, urinária e outros sangramentos; medicamentos e doações.','Investigar a fonte de acordo com idade, sintomas e risco, sem atribuir tudo à primeira explicação.'],['Há dificuldade de absorção?','Doença celíaca, cirurgia digestiva e outros contextos de má absorção.','Solicitar testes dirigidos e discutir avaliação especializada quando indicada.'],['Há inflamação ou comorbidade?','Atividade inflamatória, doença renal e evolução temporal.','Reconhecer mecanismo misto; não encerrar a análise pela PCR.'],['O padrão é antigo ou familiar?','Exames antigos, microcitose persistente e familiares com padrão semelhante.','Considerar estudo de hemoglobinas e avaliação especializada.']]}},{'h':'Perda digestiva e teste fecal: não encerrar pelo negativo','p':['Na NICE NG12, adultos com anemia ferropriva entram no fluxo de avaliação colorretal com FIT no contexto do NHS. O documento também prevê seguimento de segurança e orienta não atrasar encaminhamento quando há forte preocupação clínica apesar de FIT abaixo do limiar do fluxo.','O princípio usado aqui é manter investigação diante de sinais persistentes, como perda de peso e mudança do hábito intestinal. A escolha de exames e o encaminhamento devem seguir avaliação clínica e protocolo local; este piloto não transplanta o fluxo britânico para o Brasil.']},{'h':'Deficiência inexplicada e doença celíaca','p':['A NICE NG20 inclui deficiência de ferro inexplicada entre os motivos para oferecer investigação sorológica. Em adultos, o esquema inicial envolve IgA total e anti-transglutaminase IgA, com adaptação na deficiência de IgA. A interpretação depende da ingestão de glúten e do contexto.','O objetivo não é pedir toda sorologia para toda anemia: é reconhecer uma pergunta clínica que justifica teste dirigido. Não retirar glúten por conta própria antes de concluir a investigação, pois isso pode interferir nos testes.']},{'h':'Reavaliar sem se apoiar em um prazo inventado','p':['Uma evolução inesperada pede revisar adesão, tolerância, formulação utilizada, perdas persistentes, absorção, inflamação e o diagnóstico inicial. Melhorar a Hb não prova que a origem das perdas foi resolvida.','Não estabelecemos neste piloto um incremento universal de Hb, prazo de controle ou duração de reposição. Conferência de dose, prazo e metas nas diretrizes aplicáveis: a confirmar antes de acrescentar um módulo de tratamento.']},{'h':'Como responder em prova e no caderno','list':['Síndrome: descreva o que está alterado nas três séries.','Mecanismo: justifique deficiência absoluta, restrição inflamatória ou combinação.','Diferenciais: diga qual achado favorece ou enfraquece as principais alternativas.','Próximo passo: escolha o que resolve a dúvida ou protege de um risco, declarando o que ainda não sabe.'],'after':'Exemplo autoral: Há anemia microcítica com evidências que sugerem ferro restrito. A inflamação limita a leitura da ferritina e não exclui depleção prévia. A perda de peso e a alteração intestinal exigem investigação da causa, mesmo sem um marcador isolado conclusivo.'}],'pitfalls':['Encerrar a investigação apenas porque existe menstruação intensa.','Usar um teste fecal negativo como exclusão absoluta de neoplasia.','Chamar toda microcitose familiar de talassemia comprovada.','Esquecer que instabilidade muda a prioridade independentemente do mecanismo da anemia.'],'quiz':[{'id':'ferro-q13','level':'N3','q':'Homem mais velho tem anemia microcítica recente, perda de peso e mudança persistente do hábito intestinal. Um teste fecal foi negativo. Qual decisão é melhor?','o':['Atribuir o quadro a talassemia sem história anterior','Esperar indefinidamente pela normalização da ferritina','Manter investigação dirigida e encaminhamento conforme risco e protocolo local','Encerrar investigação digestiva pelo teste negativo'],'a':2,'why':'Sobre Manter investigação dirigida e encaminhamento conforme risco e protocolo local: Sinais persistentes mantêm preocupação clínica; a NICE prevê seguimento e encaminhamento apesar de resultado abaixo do limiar quando a suspeita é forte. Sobre Encerrar investigação digestiva pelo teste negativo: Um resultado negativo não substitui avaliação clínica nem exclui todas as causas relevantes. Sobre Atribuir o quadro a talassemia sem história anterior: Microcitose recente e sinais de alarme não autorizam esse diagnóstico por suposição. Sobre Esperar indefinidamente pela normalização da ferritina: A espera sem plano pode atrasar esclarecimento de doença importante.','explanations':{'Manter investigação dirigida e encaminhamento conforme risco e protocolo local':'Sinais persistentes mantêm preocupação clínica; a NICE prevê seguimento e encaminhamento apesar de resultado abaixo do limiar quando a suspeita é forte.','Encerrar investigação digestiva pelo teste negativo':'Um resultado negativo não substitui avaliação clínica nem exclui todas as causas relevantes.','Atribuir o quadro a talassemia sem história anterior':'Microcitose recente e sinais de alarme não autorizam esse diagnóstico por suposição.','Esperar indefinidamente pela normalização da ferritina':'A espera sem plano pode atrasar esclarecimento de doença importante.'},'refs':['cancer','idosos']},{'id':'ferro-q14','level':'N2','q':'Uma adulta tem deficiência de ferro inexplicada e sintomas digestivos persistentes. Que investigação dirigida tem fundamento nas recomendações consultadas?','o':['Pedir apenas ferritina repetidamente sem explorar a causa','Considerar doença celíaca com estratégia sorológica apropriada ao contexto','Excluir doença celíaca porque não há diarreia intensa','Suspender glúten antes de qualquer avaliação para facilitar o diagnóstico'],'a':1,'why':'Sobre Considerar doença celíaca com estratégia sorológica apropriada ao contexto: A NICE inclui deficiência inexplicada entre indicações de investigação e orienta testes iniciais apropriados. Sobre Excluir doença celíaca porque não há diarreia intensa: A apresentação pode ser variável e não exige esse sintoma isolado. Sobre Suspender glúten antes de qualquer avaliação para facilitar o diagnóstico: A retirada pode interferir nos testes; a investigação precisa ser planejada. Sobre Pedir apenas ferritina repetidamente sem explorar a causa: Repetir o marcador não responde sozinho à origem da deficiência.','explanations':{'Considerar doença celíaca com estratégia sorológica apropriada ao contexto':'A NICE inclui deficiência inexplicada entre indicações de investigação e orienta testes iniciais apropriados.','Excluir doença celíaca porque não há diarreia intensa':'A apresentação pode ser variável e não exige esse sintoma isolado.','Suspender glúten antes de qualquer avaliação para facilitar o diagnóstico':'A retirada pode interferir nos testes; a investigação precisa ser planejada.','Pedir apenas ferritina repetidamente sem explorar a causa':'Repetir o marcador não responde sozinho à origem da deficiência.'},'refs':['celiaca']},{'id':'ferro-q15','level':'N3','q':'Paciente com anemia e suspeita de deficiência de ferro chega com sangramento importante e sinais de instabilidade. Qual é a prioridade?','o':['Avaliação e atendimento da urgência, investigando a causa em paralelo','Completar todo o painel de ferro antes do atendimento','Aguardar o estudo de hemoglobinas para decidir se precisa de ajuda','Observar em casa porque a microcitose costuma ser crônica'],'a':0,'why':'Sobre Avaliação e atendimento da urgência, investigando a causa em paralelo: O estado clínico define a urgência; este exercício não determina transfusão ou medicação individual. Sobre Completar todo o painel de ferro antes do atendimento: O painel ajuda a esclarecer o mecanismo, mas não deve atrasar o atendimento da instabilidade ou do sangramento importante. Sobre Aguardar o estudo de hemoglobinas para decidir se precisa de ajuda: Esse teste não resolve a ameaça imediata de sangramento e instabilidade. Sobre Observar em casa porque a microcitose costuma ser crônica: A morfologia das hemácias não torna o quadro agudo seguro.','explanations':{'Avaliação e atendimento da urgência, investigando a causa em paralelo':'O estado clínico define a urgência; este exercício não determina transfusão ou medicação individual.','Completar todo o painel de ferro antes do atendimento':'O painel ajuda a esclarecer o mecanismo, mas não deve atrasar o atendimento da instabilidade ou do sangramento importante.','Aguardar o estudo de hemoglobinas para decidir se precisa de ajuda':'Esse teste não resolve a ameaça imediata de sangramento e instabilidade.','Observar em casa porque a microcitose costuma ser crônica':'A morfologia das hemácias não torna o quadro agudo seguro.'},'refs':['inflamacao','idosos']},{'id':'ferro-q16','level':'N3','q':'Após melhora da hemoglobina, uma pessoa continua com perda digestiva suspeita. Qual conclusão preserva o raciocínio causal?','o':['A melhora exclui qualquer doença digestiva','O tratamento retrospectivamente prova que só havia baixa ingestão','A origem é irrelevante depois de melhorar um marcador','A melhora não elimina a necessidade de esclarecer a origem das perdas'],'a':3,'why':'Sobre A melhora não elimina a necessidade de esclarecer a origem das perdas: Resposta hematológica e controle da causa são perguntas distintas. Sobre A melhora exclui qualquer doença digestiva: A melhora pode ocorrer mesmo com causa persistente. Sobre O tratamento retrospectivamente prova que só havia baixa ingestão: Diferentes causas de deficiência podem responder; a resposta não identifica a origem. Sobre A origem é irrelevante depois de melhorar um marcador: Sem esclarecer a causa, pode haver recorrência ou atraso de outro diagnóstico.','explanations':{'A melhora não elimina a necessidade de esclarecer a origem das perdas':'Resposta hematológica e controle da causa são perguntas distintas.','A melhora exclui qualquer doença digestiva':'A melhora pode ocorrer mesmo com causa persistente.','O tratamento retrospectivamente prova que só havia baixa ingestão':'Diferentes causas de deficiência podem responder; a resposta não identifica a origem.','A origem é irrelevante depois de melhorar um marcador':'Sem esclarecer a causa, pode haver recorrência ou atraso de outro diagnóstico.'},'refs':['idosos','cancer']},{'id':'ferro-q17','level':'N2','q':'Uma pessoa com microcitose familiar tem estudo inicial de hemoglobinas sem alteração. Qual interpretação é mais adequada?','o':['Confirmar deficiência de ferro independentemente da ferritina','Ignorar a história porque o primeiro teste foi normal','Reavaliar hipótese, estado do ferro e necessidade de investigação especializada','Excluir todas as hemoglobinopatias definitivamente'],'a':2,'why':'Sobre Reavaliar hipótese, estado do ferro e necessidade de investigação especializada: O alcance do teste e o fenótipo precisam ser considerados; um exame inicial não responde a todas as hipóteses. Sobre Excluir todas as hemoglobinopatias definitivamente: A normalidade do estudo inicial não cobre todas as formas de talassemia. Sobre Confirmar deficiência de ferro independentemente da ferritina: Um estudo de hemoglobinas sem alteração não mede os estoques de ferro; são perguntas diagnósticas diferentes. Sobre Ignorar a história porque o primeiro teste foi normal: A história ajuda a escolher investigação complementar e a interpretar o teste.','explanations':{'Reavaliar hipótese, estado do ferro e necessidade de investigação especializada':'O alcance do teste e o fenótipo precisam ser considerados; um exame inicial não responde a todas as hipóteses.','Excluir todas as hemoglobinopatias definitivamente':'A normalidade do estudo inicial não cobre todas as formas de talassemia.','Confirmar deficiência de ferro independentemente da ferritina':'Um estudo de hemoglobinas sem alteração não mede os estoques de ferro; são perguntas diagnósticas diferentes.','Ignorar a história porque o primeiro teste foi normal':'A história ajuda a escolher investigação complementar e a interpretar o teste.'},'refs':['inflamacao','idosos']},{'id':'ferro-q18','level':'N3','q':'Qual síntese melhor representa uma interpretação de laudo com incerteza bem comunicada?','o':['Substituir a justificativa por um número de corte não conferido','Descrever síndrome, evidências, limitações e próximo passo que resolva a dúvida','Listar todos os diagnósticos sem priorizar','Dar uma causa definitiva usando apenas o VCM'],'a':1,'why':'Sobre Descrever síndrome, evidências, limitações e próximo passo que resolva a dúvida: A síntese mostra o caminho da decisão e permite revisar hipóteses com novos dados. Sobre Listar todos os diagnósticos sem priorizar: Uma lista sem priorização não explica o que os dados favorecem nem como avançar. Sobre Dar uma causa definitiva usando apenas o VCM: O VCM é uma característica do padrão, não confirmação da causa. Sobre Substituir a justificativa por um número de corte não conferido: Número sem fonte e contexto acrescenta falsa certeza em vez de fundamentar o raciocínio.','explanations':{'Descrever síndrome, evidências, limitações e próximo passo que resolva a dúvida':'A síntese mostra o caminho da decisão e permite revisar hipóteses com novos dados.','Listar todos os diagnósticos sem priorizar':'Uma lista sem priorização não explica o que os dados favorecem nem como avançar.','Dar uma causa definitiva usando apenas o VCM':'O VCM é uma característica do padrão, não confirmação da causa.','Substituir a justificativa por um número de corte não conferido':'Número sem fonte e contexto acrescenta falsa certeza em vez de fundamentar o raciocínio.'},'refs':['inflamacao','idosos']}],'refs':['idosos','inflamacao','cancer','celiaca']}],'CASES':[{'id':'lab_ferro_c01','focus':'Estoques reduzidos e perda menstrual','stem':'Adulta de 35 anos, cansaço progressivo e menstruação descrita como intensa. Sem sangramento agudo ou instabilidade no cenário.','table':{'head':['Dado do caso fictício','Resultado'],'rows':[['Hb','9,6 g/dL'],['Ht','30,8%'],['Hemácias','4,4 milhões/µL'],['VCM','70 fL'],['Ferritina','6 ng/mL, sinalizada como baixa'],['Ferro','24 µg/dL'],['Capacidade total de ligação','400 µg/dL'],['PCR','Dentro do intervalo do laboratório']]},'ask':'Interprete o conjunto, explique o mecanismo e justifique o próximo passo antes de abrir a resolução.','answer':['A relação Ht × 10 / hemácias fornece VCM de 70 fL.','Ferritina baixa e baixa disponibilidade de ferro, sem inflamação relevante no cenário, favorecem deficiência absoluta.','Saturação aritmética: 24/400 × 100 = 6%.','A perda menstrual orienta investigação, sem excluir causas adicionais por si só.','A reposição e seu regime não são prescritos neste caso; prioridade é interpretar e esclarecer a origem.'],'stages':[{'id':'c01s1','h':'Identifique o padrão','text':'O laboratório fictício sinaliza Hb e VCM abaixo dos intervalos locais. Demais séries sem alertas.','table':{'head':['Análise ou dado','Resultado fictício'],'rows':[['Hb','9,6 g/dL'],['Ht','30,8%'],['Hemácias','4,4 milhões/µL'],['VCM','70 fL']]},'ask':'Qual conclusão esses dados permitem?','o':['Anemia com microcitose; a causa ainda precisa ser esclarecida','Ferropenia confirmada apenas pelo VCM','Talassemia confirmada apenas pelo número de hemácias'],'a':0,'explanations':['O padrão está definido, mas ainda faltam evidências de estoque e contexto.','Tamanho das hemácias não confirma estoque reduzido.','A contagem não comprova hemoglobinopatia.'],'refs':['inflamacao','idosos']},{'id':'c01s2','h':'Integre o ferro e a causa','text':'Na continuação, a ferritina é sinalizada como reduzida e a PCR dentro do intervalo do método. A coleta foi adequada.','table':{'head':['Análise ou dado','Resultado fictício'],'rows':[['Ferritina','6 ng/mL, sinalizada como baixa'],['Ferro','24 µg/dL'],['Capacidade total de ligação','400 µg/dL'],['PCR','Dentro do intervalo do laboratório']]},'ask':'Qual próximo passo integra melhor a informação?','o':['Encerrar investigação porque há uma explicação menstrual','Concluir que a saturação é 60% e indicar sobrecarga','Reconhecer provável deficiência absoluta, investigar a perda e avaliar outras causas conforme história'],'a':2,'explanations':['A história é importante, mas não prova que seja a única causa nem dispensa avaliação dirigida.','A conta correta é 24/400 × 100 = 6%; a conclusão proposta resulta de erro.','O conjunto sustenta estoques reduzidos; investigar a origem continua necessário.'],'refs':['inflamacao','idosos']}],'refs':['inflamacao','idosos']},{'id':'lab_ferro_c02','focus':'Restrição inflamatória','stem':'Adulta de 52 anos com doença inflamatória em atividade e fadiga. Não há história de deficiência anterior documentada.','table':{'head':['Dado do caso fictício','Resultado'],'rows':[['Hb','10,4 g/dL'],['VCM','78 fL, abaixo do intervalo local'],['Ferritina','180 ng/mL'],['PCR','56 mg/L, sinalizada como elevada'],['Ferro','20 µg/dL'],['Capacidade total de ligação','200 µg/dL'],['Saturação calculada','10%']]},'ask':'Interprete o conjunto, explique o mecanismo e justifique o próximo passo antes de abrir a resolução.','answer':['A saturação é 20/200 × 100 = 10%.','A atividade inflamatória pode aumentar hepcidina e reduzir exportação de ferro.','O perfil favorece restrição inflamatória e não comprova estoque adequado nem exclui mecanismo misto.','Investigar perdas, estado do ferro anterior, rim e outras causas conforme o contexto.'],'stages':[{'id':'c02s1','h':'Observe o que os marcadores medem','text':'O laboratório fictício sinaliza anemia, microcitose discreta e PCR aumentada.','table':{'head':['Análise ou dado','Resultado fictício'],'rows':[['Hb','10,4 g/dL'],['VCM','78 fL, abaixo do intervalo local'],['Ferritina','180 ng/mL'],['PCR','56 mg/L, sinalizada como elevada']]},'ask':'A ferritina basta para afirmar que a medula recebe ferro suficiente?','o':['Sim; ferritina é medida direta de ferro entregue à medula','Sim; inflamação impede qualquer anemia relacionada ao ferro','Não; fase aguda limita essa inferência'],'a':2,'explanations':['São perguntas fisiológicas distintas.','Inflamação pode restringir ferro e coexistir com deficiência absoluta.','Ferritina pode aumentar na inflamação e não mede diretamente a entrega à medula.'],'refs':['inflamacao','idosos']},{'id':'c02s2','h':'Calcule e mantenha a incerteza','text':'Agora estão disponíveis os parâmetros de ferro circulante.','table':{'head':['Análise ou dado','Resultado fictício'],'rows':[['Ferro','20 µg/dL'],['Capacidade total de ligação','200 µg/dL'],['Saturação calculada','10%']]},'ask':'Qual interpretação é mais sustentada?','o':['A anemia deve ser ignorada porque existe inflamação','Restrição inflamatória é favorecida; deficiência absoluta associada não foi excluída','Ferropenia isolada está definitivamente comprovada'],'a':1,'explanations':['A presença de inflamação não elimina a necessidade de avaliar anemia e outros mecanismos.','O conjunto é compatível com hepcidina e ferro restrito; investigar coexistência depende da história e de dados adicionais.','O perfil não confirma sozinho depleção absoluta sem contribuição inflamatória.'],'refs':['inflamacao','idosos']}],'refs':['inflamacao','idosos']},{'id':'lab_ferro_c03','focus':'Anemia recente e sinais de preocupação digestiva','stem':'Adulto de 68 anos, perda de peso não intencional e mudança persistente do hábito intestinal, com anemia recente. Está estável neste cenário fictício.','table':{'head':['Dado do caso fictício','Resultado'],'rows':[['Hb','8,8 g/dL'],['VCM','68 fL'],['Ferritina','85 ng/mL'],['PCR','60 mg/L, sinalizada como elevada'],['Ferro / capacidade','14 / 200 µg/dL'],['FIT','Abaixo do limiar do fluxo local'],['Evolução','Perda de peso e mudança intestinal persistentes']]},'ask':'Interprete o conjunto, explique o mecanismo e justifique o próximo passo antes de abrir a resolução.','answer':['Identificar anemia microcítica recente com redução de disponibilidade de ferro.','Não excluir deficiência absoluta com ferritina isolada em contexto inflamatório.','Reconhecer sinais digestivos persistentes como razão para investigação dirigida.','FIT abaixo de limiar não dispensa seguimento de segurança ou encaminhamento quando a preocupação clínica é forte.','Não se definiu diagnóstico de câncer, indicação individual de transfusão ou um exame obrigatório para todo adulto.'],'stages':[{'id':'c03s1','h':'Não transforme ferritina em garantia','text':'O painel foi coletado durante doença inflamatória concomitante.','table':{'head':['Análise ou dado','Resultado fictício'],'rows':[['Hb','8,8 g/dL'],['VCM','68 fL'],['Ferritina','85 ng/mL'],['PCR','60 mg/L, sinalizada como elevada'],['Ferro / capacidade','14 / 200 µg/dL']]},'ask':'Qual conclusão é mais apropriada?','o':['Microcitose recente com perda de peso confirma talassemia','Há anemia microcítica e ferro restrito; a inflamação impede excluir depleção pela ferritina isolada','Ferritina de 85 exclui deficiência em qualquer adulto'],'a':1,'explanations':['Padrão recente e sinais de preocupação exigem avaliação, não rótulo hereditário por suposição.','A saturação calculada é 7%; o conjunto não encerra a avaliação dos estoques e da causa.','Não foi estabelecido esse limite universal, especialmente com inflamação.'],'refs':['inflamacao','idosos']},{'id':'c03s2','h':'Interprete o teste negativo no contexto','text':'O FIT veio abaixo do limite de encaminhamento do fluxo que o serviço está usando. Os sintomas persistem.','table':{'head':['Análise ou dado','Resultado fictício'],'rows':[['FIT','Abaixo do limiar do fluxo local'],['Evolução','Perda de peso e mudança intestinal persistentes']]},'ask':'O que melhor protege contra encerramento indevido?','o':['Manter investigação e encaminhamento conforme risco, com seguimento de segurança','Encerrar avaliação digestiva porque o FIT veio abaixo do limiar','Repetir apenas o hemograma indefinidamente'],'a':0,'explanations':['A NICE prevê não atrasar encaminhamento quando há forte preocupação clínica apesar do resultado; adaptar ao protocolo local.','Um resultado isolado não resolve a preocupação clínica persistente.','Repetir o marcador sem investigar a causa pode atrasar um diagnóstico relevante.'],'refs':['cancer','idosos']}],'refs':['cancer','inflamacao','idosos']},{'id':'lab_ferro_c04','focus':'Microcitose antiga e familiar','stem':'Adulto de 23 anos, sem sintomas, com VCM baixo desde a adolescência. O pai relata padrão semelhante.','table':{'head':['Dado do caso fictício','Resultado'],'rows':[['Hb','12,2 g/dL, abaixo do intervalo local'],['Hemácias','6,0 milhões/µL'],['Ht','39%'],['VCM','65 fL'],['Ferritina','90 ng/mL'],['PCR','Dentro do intervalo local'],['Estudo inicial','Sem alteração detectada pelo método'],['Trajetória','Microcitose persistente e familiar']]},'ask':'Interprete o conjunto, explique o mecanismo e justifique o próximo passo antes de abrir a resolução.','answer':['O VCM calculado por 39 × 10 / 6 é 65 fL.','O padrão antigo e familiar sugere considerar hemoglobinopatia, mas não confirma uma forma específica.','Interpretar o estudo inicial segundo o alcance do método.','Avaliar estado do ferro e necessidade de investigação especializada sem prescrever reposição automática.'],'stages':[{'id':'c04s1','h':'Use a trajetória','text':'O laboratório fictício informa anemia discreta e microcitose, com hemácias relativamente preservadas.','table':{'head':['Análise ou dado','Resultado fictício'],'rows':[['Hb','12,2 g/dL, abaixo do intervalo local'],['Hemácias','6,0 milhões/µL'],['Ht','39%'],['VCM','65 fL'],['Ferritina','90 ng/mL'],['PCR','Dentro do intervalo local']]},'ask':'Qual hipótese merece investigação dirigida?','o':['Hemoglobinopatia, sem dispensar avaliação do estado do ferro','Ferropenia confirmada pela microcitose','Doença inflamatória confirmada apesar de contexto ausente'],'a':0,'explanations':['A história e a preservação relativa de hemácias orientam, sem confirmar o diagnóstico.','A microcitose tem outras causas e falta demonstração de depleção.','O padrão não fornece a comprovação proposta.'],'refs':['inflamacao','idosos']},{'id':'c04s2','h':'Conheça o alcance do exame','text':'O estudo inicial de hemoglobinas não mostra alteração. A história familiar e a microcitose persistem.','table':{'head':['Análise ou dado','Resultado fictício'],'rows':[['Estudo inicial','Sem alteração detectada pelo método'],['Trajetória','Microcitose persistente e familiar']]},'ask':'Qual é a melhor interpretação?','o':['Excluir todas as formas de talassemia definitivamente','Repor ferro indefinidamente sem demonstrar deficiência','Reavaliar a investigação com atenção às formas não detectadas pelo exame inicial'],'a':2,'explanations':['O alcance do método impede essa exclusão universal.','Não se demonstrou deficiência que justifique essa conclusão terapêutica.','O teste inicial não cobre todas as formas; a próxima etapa depende do fenótipo e da avaliação especializada.'],'refs':['inflamacao','idosos']}],'refs':['idosos','inflamacao']},{'id':'lab_ferro_c05','focus':'Mecanismo misto e unidades','stem':'Adulta de 42 anos com deficiência de ferro documentada antes de uma doença inflamatória recente. Não houve reposição nem correção da causa desde a amostra anterior.','table':{'head':['Dado do caso fictício','Resultado'],'rows':[['Ferro','20 µg/dL'],['Capacidade de ligação','Em µmol/L no primeiro relatório'],['Ferritina atual','140 ng/mL'],['PCR','50 mg/L, sinalizada como elevada'],['Ferro / capacidade reemitidos','20 / 250 µg/dL'],['Saturação calculada','8%'],['Ferritina antes da inflamação','8 ng/mL, sinalizada como baixa'],['Evolução','Sem reposição; ferritina sobe junto com a PCR']]},'ask':'Interprete o conjunto, explique o mecanismo e justifique o próximo passo antes de abrir a resolução.','answer':['Primeiro corrigir a incompatibilidade de unidades, sem estimar conversão por memória.','A nova conta é 20/250 × 100 = 8%.','Depleção prévia documentada não foi tratada; inflamação altera a leitura atual.','O mecanismo misto é plausível e deve orientar investigação da causa e avaliação clínica.'],'stages':[{'id':'c05s1','h':'Conferência dimensional','text':'O laboratório apresenta o painel em unidades distintas.','table':{'head':['Análise ou dado','Resultado fictício'],'rows':[['Ferro','20 µg/dL'],['Capacidade de ligação','Em µmol/L no primeiro relatório'],['Ferritina atual','140 ng/mL'],['PCR','50 mg/L, sinalizada como elevada']]},'ask':'Qual atitude é correta antes de calcular saturação?','o':['Dividir os valores diretamente porque ambos se referem ao ferro','Dividir ferritina por PCR para substituir a saturação','Obter unidades compatíveis e confirmar que o denominador é capacidade de ligação'],'a':2,'explanations':['Analitos relacionados não anulam a necessidade de conferir unidades.','Essa razão não mede saturação de transferrina.','A razão exige compatibilidade de unidades e de grandezas.'],'refs':['inflamacao','idosos']},{'id':'c05s2','h':'Não apague o exame anterior','text':'O laboratório reemite o painel em unidades compatíveis, e o registro anterior fica disponível.','table':{'head':['Análise ou dado','Resultado fictício'],'rows':[['Ferro / capacidade reemitidos','20 / 250 µg/dL'],['Saturação calculada','8%'],['Ferritina antes da inflamação','8 ng/mL, sinalizada como baixa'],['Evolução','Sem reposição; ferritina sobe junto com a PCR']]},'ask':'Qual síntese melhor integra a trajetória?','o':['Afirmar que os mecanismos nunca coexistem','Considerar deficiência absoluta prévia com restrição inflamatória associada','Declarar estoques corrigidos apenas porque a ferritina subiu'],'a':1,'explanations':['A combinação de mecanismos é possível e é central neste caso.','A fase aguda pode explicar elevação do marcador sem demonstrar correção da depleção anterior.','A ferritina atual não prova essa mudança causal ou reposição de estoques.'],'refs':['inflamacao','idosos']}],'refs':['inflamacao','idosos']}],'limitations':['Sem revisão docente externa.','Posologia de reposição nas fichas contextuais; limiares transfusionais não definidos neste piloto.','Limites diagnósticos universais de ferritina de AGA, BSG e OMS: a confirmar nesta rodada.','Sem imagens: não houve figura licenciada necessária e conferida para este piloto.','Integrado ao curso de Hemograma; revisão docente externa e teste em Safari físico pendentes.'],'educationalIntervals':[1,3,7]};

window.MASTER_LAB_FERROPENIA.MODULES[2].sections.push({h:'Reposição quando a deficiência foi demonstrada',p:['Ferro oral exige uma indicação além da microcitose. Abra a ficha de sulfato ferroso em Posologia e orientações de uso para conferir ferro elementar, via, frequência, duração e manejo de intolerância. A investigação de sangramento ou má absorção continua em paralelo.','Ferro intravenoso exige escolha do complexo e da apresentação; não converter mg do sal oral em dose IV. Persistência da anemia pede revisão de adesão, perdas, absorção, inflamação e diagnósticos associados.']});
